// ==========================================
// DGCRM — PDF FONT WITH THE RUPEE SIGN
// ==========================================
// jsPDF's built-in fonts (Helvetica) have no ₹ glyph, so PDFs wrote "Rs.".
// This is Roboto (Apache 2.0 licence) cut down to Latin letters, digits,
// punctuation and ₹ — about 31 KB per weight — embedded so a PDF can show
// "₹ 1,50,000". Loaded only when a PDF that uses it is exported.
import type { jsPDF } from 'jspdf';

export const RUPEE_FONT = 'Roboto';

const REGULAR = '';
const BOLD = '';

/** Adds the font to this document and makes it the current font. */
export function useRupeeFont(doc: jsPDF): void {
  doc.addFileToVFS('Roboto-Regular.ttf', REGULAR);
  doc.addFont('Roboto-Regular.ttf', RUPEE_FONT, 'normal');
  doc.addFileToVFS('Roboto-Bold.ttf', BOLD);
  doc.addFont('Roboto-Bold.ttf', RUPEE_FONT, 'bold');
  doc.setFont(RUPEE_FONT, 'normal');
}
